51: template <typename F>
52: void findT(const std::string& buffer, int& offset, F predicate)
53: {
54: 	bool backslashed = false;
55: 	bool found = false;
56: 
57: 	for (; offset < buffer.size(); ++offset)
58: 	{
59: 		if (backslashed)
60: 		{
61: 			backslashed = false;
62: 			continue;
63: 		}
64: 
65: 		char c = buffer[offset];
66: 		if (predicate(c))
67: 		{
68: 			found = true;
69: 			break;
70: 		}
71: 		else if (c == '\\')
72: 		{
73: 			backslashed = true;
74: 		}
75: 	}
76: 
77: 	if (!found)
78: 		offset = -1;
79: }
