131: auto&& cxx_string = std::regex{"^(?:u8|u|U|L)?\"(?:[^\n\"\\\\]|\\\\['\"?\\\\a-zA-Z0-9])*\""};
132: auto&& longstring = std::regex{"^(?:u8|u|U|L)?\"\"\"([^\"\\\\]|\\\\['\"?\\\\a-zA-Z0-9])*\"\"\""};
133: auto&& integer    = std::regex{"^[0-9]+"};
