135: template <char terminator>
136: auto Tokenizer::tokenize_single() -> optional<Token>
137: {
138: 	// let begin = int(pos)
139: 	auto&& begin = freeze(int(pos));
140: 
141: 	// TODO handle ud-suffix
142: 	auto match = std::smatch{};
143: 	if (std::regex_search(data.cbegin() + pos, data.cend(), match, cxx_string))
144: 	{
145: 		pos += match[0].length();
146: 		return Token{Token::Atom, match[0].str()};
147: 	}
148: 	if (std::regex_search(data.cbegin() + pos, data.cend(), match, longstring))
149: 	{
150: 		pos += match[0].length();
151: 		return Token{Token::Atom, match[0].str()};
152: 	}
153: 	if (std::regex_search(data.cbegin() + pos, data.cend(), match, integer))
154: 	{
155: 		pos += match[0].length();
156: 		return Token{Token::Atom, match[0].str()};
157: 	}
158: 
159: 	// let first = data[pos++]
160: 	auto&& first = freeze(data[pos++]);
161: 
162: 	assert(!is_space[first]);
163: 
164: 	if (first == terminator)
165: 		return nullopt;
166: 
167: 	if (terminator == '\n' && is_newline[first])
168: 		return nullopt;
169: 
170: 	switch (first)
171: 	{
172: 		case '(':
173: 		{
174: 			auto&& subtokens = tokenize_until<')'>();
175: 			return Token{Token::Round, str::slice(data, begin, pos), subtokens};
176: 		}
177: 
178: 		case '[':
179: 		{
180: 			auto&& subtokens = tokenize_until<']'>();
181: 			return Token{Token::Square, str::slice(data, begin, pos), subtokens};
182: 		}
183: 
184: 		case '{':
185: 		{
186: 			auto&& subtokens = tokenize_until<'}'>();
187: 			return Token{Token::Curly, str::slice(data, begin, pos), subtokens};
188: 		}
189: 
190: 		case ')':
191: 		case ']':
192: 		case '}':
193: 			throw SyntaxError("invalid syntax");
194: 
195: 		case '-':
196: 			if (pos < data.size())
197: 				switch (data[pos])
198: 				{
199: 					case '>':
200: 						++pos;
201: 				}
202: 			break;
203: 	}
204: 
205: 	if (!is_special[first])
206: 	{
207: 		findBoundary(data, pos);
208: 
209: 		if (pos == -1)
210: 			pos = data.size();
211: 	}
212: 
213: 	if (begin == pos)
214: 	{
215: 		if (terminator == '\n')
216: 			return nullopt;
217: 		else
218: 			throw SyntaxError("unexpected EOF while parsing");
219: 	}
220: 
221: 	if (is_special[first])
222: 		return Token{Token::Other, str::slice(data, begin, pos)};
223: 	else
224: 		return Token{Token::Identifier, str::slice(data, begin, pos)};
225: }
