227: template <char terminator>
228: auto Tokenizer::tokenize_until() -> vector<Token>
229: {
230: 	auto&& tokens = vector<Token>{};
231: 
232: 	while (pos < data.size())
233: 	{
234: 		for (; pos < data.size() && is_space[data[pos]]; ++pos)
235: 		{
236: 			if (terminator == '\n')
237: 			{
238: 				if (tokens.size() && is_newline[data[pos]])
239: 				{
240: 					++pos;
241: 					return tokens;
242: 				}
243: 			}
244: 		}
245: 
246: 		if (pos < data.size())
247: 		{
248: 			auto&& t = tokenize_single<terminator>();
249: 			if (!t)
250: 				break;
251: 			tokens.emplace_back(*t);
252: 		}
253: 	}
254: 
255: 	return tokens;
256: }
257: 
258: auto Tokenizer::tokenize_statement() -> vector<Token>
259: {
260: 	return tokenize_until<'\n'>();
261: }
