263: void Tokenizer::read_prefix()
264: {
265: 	auto&& begin = int(pos);
266: 
267: 	for (; pos < data.size() && is_space[data[pos]]; ++pos)
268: 	{
269: 		if (is_newline[data[pos]])
270: 			begin = pos + 1;
271: 	}
272: 
273: 	prefix = str::slice(data, begin, pos);
274: }
275: 
276: auto Tokenizer::tokenize_block(string block_prefix) -> vector<Statement>
277: {
278: 	init_is_space_special();
279: 
280: 	auto&& block = vector<Statement>{};
281: 
282: 	while (pos < data.size())
283: 	{
284: 		auto stmt = Statement{tokenize_statement()};
285: 
286: 		read_prefix();
287: 
288: 		if (stmt.tokens[stmt.tokens.size()-1].code == ":")
289: 		{
290: 			if (!str::startswith(prefix, block_prefix))
291: 				throw TabError("inconsistent use of tabs and spaces in indentation");
292: 			else if (prefix.size() <= block_prefix.size())
293: 				throw IndentationError("expected an indented block");
294: 
295: 			stmt.block = tokenize_block(prefix);
296: 		}
297: 
298: 		block.emplace_back(move(stmt));
299: 
300: 		if (prefix != block_prefix)
301: 		{
302: 			if (prefix.size() < block_prefix.size())
303: 				break;
304: 			else if (!str::startswith(prefix, block_prefix))
305: 				throw TabError("inconsistent use of tabs and spaces in indentation");
306: 			else if (prefix.size() != block_prefix.size())
307: 				throw IndentationError("unexpected indent");
308: 		}
309: 	}
310: 
311: 	return block;
